const TransferTicketsScreen = ({ order, onCancel, onComplete }) => {
  const [selectedTickets, setSelectedTickets] = useState([]);
  const toggleTicket = (seat) => setSelectedTickets((current) => current.includes(seat) ? current.filter((item) => item !== seat) : [...current, seat]);
  const toggleAll = () => setSelectedTickets((current) => current.length === order.seats.length ? [] : [...order.seats]);
  return <SafeAreaView style={styles.transferScreen} edges={['top']}><View style={styles.transferHeader}><TouchableOpacity onPress={onCancel} style={styles.transferClose}><Text style={styles.transferCloseText}>×</Text></TouchableOpacity><Text style={styles.transferHeaderTitle}>Transfer Tickets</Text><View style={styles.transferHeaderSpacer} /></View><ScrollView contentContainerStyle={styles.transferContent}><Image source={{ uri: order.event.image }} style={styles.transferEventImage} /><View style={styles.transferEventInfo}><Text style={styles.transferEventName}>{order.event.name}</Text><Text style={styles.transferEventMeta}>{day(order.event)} · {order.event.time}</Text><Text style={styles.transferEventMeta}>{order.event.venue}</Text></View><Text style={styles.transferTitle}>Transfer Tickets</Text><Text style={styles.transferCopy}>Select the tickets for this event that you would like to transfer. Once selected, tap Continue.</Text><View style={styles.transferListHeader}><Text style={styles.transferListTitle}>TICKETS</Text><Text style={styles.transferCount}>Selected ({selectedTickets.length} of {order.seats.length})</Text></View><TouchableOpacity onPress={toggleAll} style={styles.selectAllRow}><View style={[styles.transferCheckbox, selectedTickets.length === order.seats.length && styles.transferCheckboxSelected]}>{selectedTickets.length === order.seats.length && <Text style={styles.transferCheck}>✓</Text>}</View><Text style={styles.selectAllText}>Select all tickets</Text></TouchableOpacity>{order.seats.map((seat, index) => <TouchableOpacity key={`${seat}-${index}`} onPress={() => toggleTicket(seat)} style={styles.transferTicketRow}><View style={[styles.transferCheckbox, selectedTickets.includes(seat) && styles.transferCheckboxSelected]}>{selectedTickets.includes(seat) && <Text style={styles.transferCheck}>✓</Text>}</View><View><Text style={styles.transferSeatText}>{seat.replaceAll('-', ' · ')}</Text><Text style={styles.transferSeatSub}>Ticket {index + 1} of {order.quantity}</Text></View></TouchableOpacity>)}</ScrollView><View style={styles.transferFooter}><TouchableOpacity onPress={onCancel} style={styles.cancelTransfer}><Text style={styles.cancelTransferText}>Cancel</Text></TouchableOpacity><TouchableOpacity disabled={!selectedTickets.length} onPress={() => onComplete(selectedTickets)} style={[styles.continueTransfer, !selectedTickets.length && styles.continueTransferDisabled]}><Text style={styles.continueTransferText}>Continue</Text></TouchableOpacity></View></SafeAreaView>;
};

